#!/usr/bin/env bash
set -Eeuo pipefail

# RIX STORM one-command setup for a clean Debian/Ubuntu VPS.
# Example: bash install_xray_agent.sh --domain vpn.example.com --agent-token TOKEN --panel-url https://panel.example.com
DOMAIN=""
AGENT_TOKEN=""
PANEL_URL=""
PORT_START="20000"
PORT_END="20100"
REALITY_SNI="www.microsoft.com"

usage() {
  cat <<'EOF'
RIX STORM automatic VPS installer
Required:
  --domain DOMAIN          Public DNS name pointing to this VPS
  --agent-token TOKEN      Long random token generated by the panel
  --panel-url URL          Public HTTPS address of the RIX STORM panel
Optional:
  --port-start NUMBER      First client port (default 20000)
  --port-end NUMBER        Last client port (default 20100)
  --reality-sni DOMAIN     Reality destination SNI (default www.microsoft.com)
EOF
}
while (($#)); do
  case "$1" in
    --domain) DOMAIN="${2:-}"; shift 2 ;;
    --agent-token) AGENT_TOKEN="${2:-}"; shift 2 ;;
    --panel-url) PANEL_URL="${2:-}"; shift 2 ;;
    --port-start) PORT_START="${2:-}"; shift 2 ;;
    --port-end) PORT_END="${2:-}"; shift 2 ;;
    --reality-sni) REALITY_SNI="${2:-}"; shift 2 ;;
    -h|--help) usage; exit 0 ;;
    *) echo "Unknown option: $1" >&2; usage; exit 2 ;;
  esac
done

if [[ "$(id -u)" -ne 0 ]]; then echo "Run this command as root (the panel command uses sudo)." >&2; exit 1; fi
if [[ ! -f /etc/debian_version ]]; then echo "Automatic setup supports Debian/Ubuntu only. Use a clean Debian 12 or Ubuntu 22.04/24.04 VPS." >&2; exit 1; fi
if [[ ! "$DOMAIN" =~ ^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}$ ]]; then
  echo "A real DNS domain is required for automatic HTTPS (an IP address is not enough for this setup)." >&2; exit 1
fi
DOMAIN="$(printf '%s' "$DOMAIN" | tr '[:upper:]' '[:lower:]')"
if [[ "$PANEL_URL" != https://* ]]; then echo "--panel-url must start with https://" >&2; exit 1; fi
PANEL_URL="${PANEL_URL%/}"
if [[ ! "$AGENT_TOKEN" =~ ^[A-Za-z0-9_-]{32,}$ ]]; then echo "The Agent token must be at least 32 URL-safe random characters." >&2; exit 1; fi
if ! [[ "$PORT_START" =~ ^[0-9]+$ && "$PORT_END" =~ ^[0-9]+$ ]] || ((PORT_START < 1024 || PORT_END > 65535 || PORT_END < PORT_START || PORT_END - PORT_START > 10000)); then
  echo "Invalid client port range." >&2; exit 1
fi
if ! [[ "$REALITY_SNI" =~ ^([a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}$ ]]; then
  echo "Invalid Reality SNI domain." >&2; exit 1
fi

port_in_use() {
  local port_hex
  port_hex="$(printf '%04X' "$1")"
  awk -v suffix=":${port_hex}" '$2 ~ (suffix "$") && $4 == "0A" {found=1} END {exit !found}' /proc/net/tcp /proc/net/tcp6 2>/dev/null
}
if port_in_use 80 || port_in_use 443; then
  echo "Ports 80 or 443 are already in use. To keep existing services safe, run this installer on a fresh VPS or free these ports first." >&2
  exit 1
fi
range_in_use() {
  awk -v lo="$PORT_START" -v hi="$PORT_END" '
    function hv(c) { c=toupper(c); return index("0123456789ABCDEF", c)-1 }
    function hnum(s, i, n) { n=0; for (i=1; i<=length(s); i++) n=n*16+hv(substr(s,i,1)); return n }
    ($4 == "0A" || $4 == "07") { split($2, ep, ":"); p=hnum(ep[2]); if (p>=lo && p<=hi) { printf "%s ", p; found=1 } }
    END { if (found) print ""; exit !found }
  ' /proc/net/tcp /proc/net/tcp6 /proc/net/udp /proc/net/udp6 2>/dev/null
}
OCCUPIED_PORTS="$(range_in_use || true)"
if [[ -n "$OCCUPIED_PORTS" ]]; then
  echo "Some client ports in the selected range are already bound: ${OCCUPIED_PORTS}. Choose a free range or use a fresh VPS." >&2
  exit 1
fi
# Do not silently take over an existing reverse-proxy configuration, even if it is stopped.
for conf in /etc/nginx/sites-enabled/*; do
  [[ -e "$conf" ]] || continue
  name="$(basename "$conf")"
  if [[ "$name" != "default" && "$name" != "rix-storm-agent" ]]; then
    echo "Existing Nginx site detected ($name). The installer will not modify an existing web setup; use a fresh VPS or coordinate a manual migration." >&2
    exit 1
  fi
done
for conf in /etc/nginx/conf.d/*.conf; do
  [[ -e "$conf" ]] || continue
  echo "Existing Nginx config detected ($(basename "$conf")). The installer will not overwrite it; use a fresh VPS or coordinate a manual migration." >&2
  exit 1
done

export DEBIAN_FRONTEND=noninteractive
apt-get update
apt-get install -y ca-certificates curl unzip python3 python3-venv python3-pip nginx certbot openssl iproute2

# Never overwrite an existing Xray configuration or service. This install owns a separate service/config.
if [[ -e /etc/rix-storm/xray.json ]] && ! grep -q 'rix-storm-api-in' /etc/rix-storm/xray.json; then
  echo "Found a non-RIX config at /etc/rix-storm/xray.json; refusing to overwrite it." >&2; exit 1
fi

ARCH="$(uname -m)"
case "$ARCH" in
  x86_64|amd64) ASSET="Xray-linux-64.zip" ;;
  aarch64|arm64) ASSET="Xray-linux-arm64-v8a.zip" ;;
  *) echo "Unsupported CPU architecture: $ARCH" >&2; exit 1 ;;
esac
TMP_DIR="$(mktemp -d)"
trap 'rm -rf "$TMP_DIR"' EXIT
curl -fL --retry 3 --connect-timeout 15 "https://github.com/XTLS/Xray-core/releases/latest/download/${ASSET}" -o "$TMP_DIR/xray.zip"
unzip -q "$TMP_DIR/xray.zip" -d "$TMP_DIR/unpacked"

id -u rixagent >/dev/null 2>&1 || useradd --system --home /opt/rix-storm-agent --shell /usr/sbin/nologin rixagent
install -d -o rixagent -g rixagent -m 0750 /opt/rix-storm-agent
install -d -o root -g rixagent -m 0750 /etc/rix-storm /etc/rix-storm/tls
install -m 0755 "$TMP_DIR/unpacked/xray" /opt/rix-storm-agent/xray
chown rixagent:rixagent /opt/rix-storm-agent/xray

# Fetch the exact Agent version shipped by this panel, not an unpinned third-party copy.
curl -fL --retry 3 --connect-timeout 15 "$PANEL_URL/xray-agent.py" -o /opt/rix-storm-agent/xray_agent.py
chown rixagent:rixagent /opt/rix-storm-agent/xray_agent.py
chmod 0640 /opt/rix-storm-agent/xray_agent.py
python3 -m venv /opt/rix-storm-agent/venv
/opt/rix-storm-agent/venv/bin/pip install --disable-pip-version-check --upgrade 'pip<27'
/opt/rix-storm-agent/venv/bin/pip install --disable-pip-version-check 'fastapi>=0.115,<1.0' 'uvicorn[standard]>=0.34,<1.0'

# Obtain a real, automatically-renewed certificate for both client TLS and the HTTPS Agent.
install -d -m 0755 /var/www/certbot/.well-known/acme-challenge
cat > /etc/nginx/sites-available/rix-storm-agent <<NGINX_HTTP
server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};
    location ^~ /.well-known/acme-challenge/ {
        root /var/www/certbot;
        default_type text/plain;
        try_files \$uri =404;
    }
    location / { return 404; }
}
NGINX_HTTP
rm -f /etc/nginx/sites-enabled/default
ln -sfn /etc/nginx/sites-available/rix-storm-agent /etc/nginx/sites-enabled/rix-storm-agent
nginx -t
systemctl enable --now nginx
certbot certonly --webroot -w /var/www/certbot -d "$DOMAIN" --non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring

sync_certificate() {
  install -o root -g rixagent -m 0640 "/etc/letsencrypt/live/${DOMAIN}/privkey.pem" /etc/rix-storm/tls/privkey.pem
  install -o root -g rixagent -m 0644 "/etc/letsencrypt/live/${DOMAIN}/fullchain.pem" /etc/rix-storm/tls/fullchain.pem
  systemctl reload nginx 2>/dev/null || true
  systemctl restart rix-storm-xray 2>/dev/null || true
}

# Generate a fresh Reality keypair. Xray's newer CLI calls the public key "Password".
KEY_OUTPUT="$(/opt/rix-storm-agent/xray x25519 2>&1)"
export KEY_OUTPUT
readarray -t KEY_VALUES < <(python3 - <<'PY'
import os, re, sys
text = os.environ.get('KEY_OUTPUT', '')
private = public = ''
for line in text.splitlines():
    m = re.match(r'^\s*(PrivateKey|Private key)\s*:\s*(\S+)\s*$', line, re.I)
    if m: private = m.group(2)
    m = re.match(r'^\s*(Password\s*\(PublicKey\)|Password|PublicKey|Public key)\s*:\s*(\S+)\s*$', line, re.I)
    if m: public = m.group(2)
if not private or not public:
    print('Could not parse Xray x25519 output.', file=sys.stderr)
    sys.exit(1)
print(private)
print(public)
PY
)
REALITY_PRIVATE_KEY="${KEY_VALUES[0]}"
REALITY_PUBLIC_KEY="${KEY_VALUES[1]}"
REALITY_SHORT_ID="$(openssl rand -hex 8)"
if [[ -z "$REALITY_PRIVATE_KEY" || -z "$REALITY_PUBLIC_KEY" ]]; then
  echo "Could not create a valid Reality keypair. Check the downloaded Xray-core release." >&2
  exit 1
fi

cat > /etc/rix-storm/xray.json <<'XRAYJSON'
{
  "log": {"loglevel": "warning"},
  "api": {"tag": "rix-storm-api", "services": ["HandlerService", "LoggerService", "StatsService"]},
  "inbounds": [
    {"listen": "127.0.0.1", "port": 19085, "protocol": "dokodemo-door", "settings": {"address": "127.0.0.1"}, "tag": "rix-storm-api-in"}
  ],
  "outbounds": [
    {"protocol": "freedom", "tag": "direct"},
    {"protocol": "blackhole", "tag": "blocked"}
  ],
  "routing": {"rules": [{"type": "field", "inboundTag": ["rix-storm-api-in"], "outboundTag": "rix-storm-api"}]}
}
XRAYJSON
chown root:rixagent /etc/rix-storm/xray.json
chmod 0640 /etc/rix-storm/xray.json

cat > /etc/rix-storm-agent.env <<ENVVARS
XRAY_BIN=/opt/rix-storm-agent/xray
XRAY_API_ADDR=127.0.0.1:19085
AGENT_TOKEN=${AGENT_TOKEN}
AGENT_PORT_START=${PORT_START}
AGENT_PORT_END=${PORT_END}
AGENT_STATE_PATH=/opt/rix-storm-agent/inbounds.json
NODE_DOMAIN=${DOMAIN}
TLS_CERT_PATH=/etc/rix-storm/tls/fullchain.pem
TLS_KEY_PATH=/etc/rix-storm/tls/privkey.pem
REALITY_PRIVATE_KEY=${REALITY_PRIVATE_KEY}
REALITY_PUBLIC_KEY=${REALITY_PUBLIC_KEY}
REALITY_SHORT_ID=${REALITY_SHORT_ID}
REALITY_SNI=${REALITY_SNI}
ENVVARS
chown root:rixagent /etc/rix-storm-agent.env
chmod 0640 /etc/rix-storm-agent.env

cat > /etc/systemd/system/rix-storm-xray.service <<'SERVICE'
[Unit]
Description=RIX STORM Xray-core (separate managed instance)
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
User=rixagent
Group=rixagent
ExecStart=/opt/rix-storm-agent/xray run -config /etc/rix-storm/xray.json
Restart=on-failure
RestartSec=3
LimitNOFILE=1048576
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true
ProtectSystem=strict
ReadWritePaths=/opt/rix-storm-agent /etc/rix-storm/tls

[Install]
WantedBy=multi-user.target
SERVICE

cat > /etc/systemd/system/rix-storm-agent.service <<'SERVICE'
[Unit]
Description=RIX STORM authenticated Xray Agent
After=network-online.target rix-storm-xray.service
Wants=network-online.target

[Service]
Type=simple
User=rixagent
Group=rixagent
WorkingDirectory=/opt/rix-storm-agent
EnvironmentFile=/etc/rix-storm-agent.env
ExecStart=/opt/rix-storm-agent/venv/bin/uvicorn xray_agent:app --host 127.0.0.1 --port 9843
Restart=always
RestartSec=3
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true
ProtectSystem=strict
ReadWritePaths=/tmp /opt/rix-storm-agent

[Install]
WantedBy=multi-user.target
SERVICE

# Sync the renewed Let's Encrypt certificate to a path readable by the non-root Xray service.
cat > /etc/letsencrypt/renewal-hooks/deploy/rix-storm-sync-cert.sh <<HOOK
#!/usr/bin/env bash
set -euo pipefail
install -o root -g rixagent -m 0640 "/etc/letsencrypt/live/${DOMAIN}/privkey.pem" /etc/rix-storm/tls/privkey.pem
install -o root -g rixagent -m 0644 "/etc/letsencrypt/live/${DOMAIN}/fullchain.pem" /etc/rix-storm/tls/fullchain.pem
nginx -t && systemctl reload nginx
systemctl restart rix-storm-xray
HOOK
chmod 0750 /etc/letsencrypt/renewal-hooks/deploy/rix-storm-sync-cert.sh
sync_certificate

cat > /etc/nginx/sites-available/rix-storm-agent <<NGINX_HTTPS
server {
    listen 80;
    listen [::]:80;
    server_name ${DOMAIN};
    location ^~ /.well-known/acme-challenge/ {
        root /var/www/certbot;
        default_type text/plain;
        try_files \$uri =404;
    }
    location / { return 301 https://\$host\$request_uri; }
}
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name ${DOMAIN};
    ssl_certificate /etc/rix-storm/tls/fullchain.pem;
    ssl_certificate_key /etc/rix-storm/tls/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    client_max_body_size 2m;
    location / {
        proxy_pass http://127.0.0.1:9843;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header Authorization \$http_authorization;
        proxy_connect_timeout 10s;
        proxy_read_timeout 30s;
    }
}
NGINX_HTTPS
nginx -t
systemctl daemon-reload
systemctl enable --now rix-storm-xray
systemctl enable --now rix-storm-agent
systemctl reload nginx

# Configure UFW when it is already active; cloud-provider firewalls still need the same rules.
if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q 'Status: active'; then
  ufw allow 80/tcp >/dev/null || true
  ufw allow 443/tcp >/dev/null || true
  ufw allow "${PORT_START}:${PORT_END}/tcp" >/dev/null || true
  ufw allow "${PORT_START}:${PORT_END}/udp" >/dev/null || true
fi

sleep 2
if ! systemctl is-active --quiet rix-storm-xray; then journalctl -u rix-storm-xray -n 40 --no-pager >&2 || true; echo "Xray service did not start." >&2; exit 1; fi
if ! systemctl is-active --quiet rix-storm-agent; then journalctl -u rix-storm-agent -n 40 --no-pager >&2 || true; echo "Agent service did not start." >&2; exit 1; fi
if ! systemctl is-active --quiet nginx; then journalctl -u nginx -n 40 --no-pager >&2 || true; echo "HTTPS proxy did not start." >&2; exit 1; fi

cat <<EOF

RIX STORM automatic server setup completed.
Agent URL: https://${DOMAIN}
Client ports: ${PORT_START}-${PORT_END} (TCP and UDP)
TLS cert: /etc/rix-storm/tls/fullchain.pem
Reality SNI: ${REALITY_SNI}

Now return to RIX STORM → Servers and press "Test connection" once.
The panel will import the generated TLS and Reality settings automatically.
Open the same ports in your VPS provider firewall: TCP 80, 443 and TCP/UDP ${PORT_START}-${PORT_END}.
Check: systemctl status rix-storm-xray rix-storm-agent nginx
EOF
